fn shout_if_some(maybe: Option<String>) -> String {
    match maybe {
        Some(v) => v.to_uppercase(),
        None => String::new(),
    }
}

fn main() {
    assert_eq!(shout_if_some(Some(String::from("hi"))), "HI");
